    h, w = len(grid), len(grid[0])
    visited = set()
    components = defaultdict(list)

    for i in range(h):
        for j in range(w):
            val = grid[i][j]
            if val != 1 and (i,j) not in visited:
                comp = []
                stack = [(i,j)]
                visited.add((i,j))
                while stack:
                    r, c = stack.pop()
                    comp.append((r,c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r+dr, c+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == val and (nr,nc) not in visited:
                                visited.add((nr,nc))
                                stack.append((nr,nc))
                components[val].append(comp)
    return components

def get_color_of_region(grid, coords):
    """Get the most common color among neighbors of the given coordinates."""
    neighbors = []
    for r, c in coords:
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                val = grid[nr][nc]
                neighbors.append((val, (nr, nc)))
    from collections import Counter
    counts = Counter([n[0] for n in neighbors])
    # Exclude background (1) and self-color from consideration for majority
    non_bg_non_self = {k:v for k,v in counts.items() if k != 1}
    if non_bg_non_self:
        return max(non_bg_non_self.keys(), key=lambda k: counts[k])
    return None

